inline void prepare(){
 const auto* vram=gpu_get_vram();bool same=vram!=nullptr;
 for(int y=0;same && y<144;++y)same=std::memcmp(vram+y*1024+832,pixels+y*32,64)==0;
 if(!same){gpu_write_gp0(0xa0000000);gpu_write_gp0(832);gpu_write_gp0(32|(144u<<16));for(unsigned i=0;i<sizeof(pixels)/sizeof(*pixels);i+=2)gpu_write_gp0(pixels[i]|uint32_t(pixels[i+1])<<16);}
 // Every texel participates in semi-transparency, including the black background.
 // Retail dark captions subtract their luminance; white captions add it.
 uint16_t palette[16];for(int i=0;i<16;++i){const int shade=(i*31+7)/15;palette[i]=uint16_t(0x8000|shade|(shade<<5)|(shade<<10));}
 if(!vram || std::memcmp(vram+864,palette,32)){
 gpu_write_gp0(0xa0000000);gpu_write_gp0(864);gpu_write_gp0(16|(1u<<16));for(int i=0;i<16;i+=2)gpu_write_gp0(palette[i]|uint32_t(palette[i+1])<<16);}
}
inline void draw(CPUState* c,Image image,int x,int y,bool black=false){prepare();rage_menu::quad(c,x,y,image.w,image.h,image.u,image.v,image.w,image.h,0x36,black?0x4d:0x2d,0x2f808080);}

inline void scripted(CPUState* c,Image image,bool black=false){
 const uint32_t m=c->gpr[6];int elapsed=std::min(int32_t(c->gpr[4]),int32_t(c->read_word(m)));
 auto offset=[&](int velocity){return int32_t(uint32_t(elapsed)*uint32_t(velocity)/32);};
 const uint32_t velocity=c->read_word(m+16);
 draw(c,image,int16_t(c->read_half(m+4)+offset(int16_t(velocity))),int16_t(c->read_half(m+6)+offset(int16_t(velocity>>16))),black);
}
